const raw = $json.body ?? $json;
const output = [];

function emitValue(value) {
  if (!value || typeof value !== 'object') return;

  const contacts = Array.isArray(value.contacts) ? value.contacts : [];
  const messages = Array.isArray(value.messages) ? value.messages : [];
  const statuses = Array.isArray(value.statuses) ? value.statuses : [];
  const phoneNumberId = value.metadata?.phone_number_id ?? null;

  for (const message of messages) {
    if (message?.type !== 'text' || !message?.text?.body || !message?.id || !message?.from) {
      continue;
    }

    const contact = contacts.find((item) => item?.wa_id === message.from) ?? contacts[0] ?? {};
    output.push({
      json: {
        kind: 'inbound',
        tia_payload: {
          external_event_id: `message:${message.id}`,
          external_message_id: message.id,
          external_user_id: message.from,
          external_conversation_id: message.from,
          display_name: contact?.profile?.name ?? null,
          phone: message.from,
          message_type: 'text',
          text: message.text.body,
          metadata: {
            provider: 'meta_cloud',
            phone_number_id: phoneNumberId,
            whatsapp_timestamp: message.timestamp ?? null,
            whatsapp_type: message.type,
            context_message_id: message.context?.id ?? null,
          },
        },
      },
    });
  }

  const supportedStatuses = new Set(['sent', 'delivered', 'read', 'failed']);
  for (const status of statuses) {
    if (!status?.id || !supportedStatuses.has(status?.status)) continue;

    const timestamp = status.timestamp ?? '0';
    const seconds = Number(timestamp);
    const occurredAt = Number.isFinite(seconds) && seconds > 0
      ? new Date(seconds * 1000).toISOString()
      : null;
    const firstError = Array.isArray(status.errors) ? status.errors[0] : null;

    output.push({
      json: {
        kind: 'status',
        tia_payload: {
          external_event_id: `status:${status.id}:${status.status}:${timestamp}`,
          provider_message_id: status.id,
          status: status.status,
          occurred_at: occurredAt,
          error: firstError?.title ?? firstError?.message ?? null,
          metadata: {
            provider: 'meta_cloud',
            recipient_id: status.recipient_id ?? null,
            conversation: status.conversation ?? null,
            pricing: status.pricing ?? null,
            errors: status.errors ?? null,
          },
        },
      },
    });
  }
}

if (Array.isArray(raw.entry)) {
  for (const entry of raw.entry) {
    for (const change of entry?.changes ?? []) emitValue(change?.value);
  }
} else if (raw.value) {
  emitValue(raw.value);
} else {
  emitValue(raw);
}

return output;
